import{_ as o,l as r,o as a,c as i,v as t,p as d,x as l,d as s,i as A,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"内核自动调优","description":"","frontmatter":{"title":"内核自动调优","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kernel-autotuning.md","filePath":"llm/kernel-autotuning.md","lastUpdated":1789023840000}'),p={name:"llm/kernel-autotuning.md"};function c(u,e,m,E,_,T){const n=r("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="内核自动调优" tabindex="-1">内核自动调优 <a class="header-anchor" href="#内核自动调优" aria-label="Permalink to &quot;内核自动调优&quot;">​</a></h1><div class="epigraph"><p>同一算法的块大小、流水深度和向量宽度是硬件相关的离散空间；靠编译器或运行时搜一轮，往往比手写一组「通用」常量更接近屋顶。</p><footer>—— Chen et al., TVM, OSDI 2018；Ansor：Zheng et al., OSDI 2020；Triton 的 autotune 为运行时网格搜索</footer></div><p><a href="/llm/torch-compile-inductor">上一课</a>把算子融进 Triton/CUDA。融完之后仍有离散超参：tile、\\(B_r,B_c\\)、warp 数。TVM 把张量程序与自动调度分开；Ansor 用层次化搜索生成调度；Triton <code>@triton.autotune</code> 在若干配置上计时取最快。FlashAttention 的块大小同样是 SRAM 容量约束下的搜索，不是公式给出的唯一整数。本课写 <em>何时搜、缓存键是什么</em>，避免每条请求现场扫网格把 TPOT 打穿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>会计给出的屋顶是上界。实际核用错 tile，有效带宽可能只有峰值一半。<a href="/llm/torch-compile-inductor">上一课</a>的 <code>max-autotune</code> 会触发搜索，首次极慢。服务形状又是动态的：\\(n\\)、\\(B\\)、头数、是否因果、元素类型。缺口是：搜索空间按哪些键缓存，以及动态形状如何落到最近的桶而不每步重搜。</p><p>错误配置不只是慢：共享内存溢出、占用率过低、或数值路径不同（累加顺序）。调优必须验收数值，不能只看毫秒。</p><p><span class="marginnote">CUTLASS / cuBLAS 的启发式选择也是一种自动调优，只是搜索在库内。换一种布局（HND vs BSHD）等于换了一个问题，缓存不能共用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线：对部署会见到的 \\((B,n,h,d,\\mathrm{dtype})\\) 桶跑 autotune，把最优配置写进磁盘缓存。在线：只允许在冷启动或新桶首次出现时搜，并加超时回退到安全配置。Triton 的 key 应包含动态维的量化桶，而不是原始 \\(n=137\\)。注意力核的 \\(B_c\\) 受 SRAM 与 \\(d\\) 限制，搜索空间其实不大，但 <em>每个 dtype 与是否 GQA</em> 都要单独来。</p><p>与<a href="/llm/flashattention">FlashAttention</a> 家族：FA2/FA3 已在常见头维上调过；自写 Triton 注意力才需要你自己的 autotune。不要在生产路径上对 FA 再套一层网格搜。</p>',10)),(a(),d(h,null,{default:l(()=>[A(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHAPE%5B%22%E5%BD%A2%E7%8A%B6%E6%A1%B6%20B%2Cn%2Ch%2Cdtype%22%5D%20--%3E%20GRID%5B%22%E9%85%8D%E7%BD%AE%E7%BD%91%E6%A0%BC%22%5D%0A%20%20GRID%20--%3E%20TIME%5B%22%E8%AE%A1%E6%97%B6%20%2B%20%E6%95%B0%E5%80%BC%E9%AA%8C%E6%94%B6%22%5D%0A%20%20TIME%20--%3E%20CACHE%5B%22%E7%A3%81%E7%9B%98%20%2F%20%E5%86%85%E5%AD%98%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20RUN%5B%22%E7%83%AD%E8%B7%AF%E5%BE%84%E5%8F%AA%E6%9F%A5%E8%A1%A8%22%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>搜索是在屋顶线上找更接近 \\(I_{\\star}\\) 的点：更好的 tile 提高复用、降低 bank conflict。它不改变算法复杂度。缓存命中后，decode 步不再付搜索。连续批的形状抖动若跨越桶，会看到 TPOT 锯齿——应把桶做粗，或对混合批次用「最坏形状」配置换稳定性。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要每进程冷启动全网格（集群同时扩容会打满 GPU 做调优）。多卡要按 SKU 分缓存，A100 的最优不是 H100 的。下一课离开单核，处理 TP 的集合通信：自定义 allreduce。</p><p>出处：Chen et al., OSDI 2018；Zheng et al., OSDI 2020；Tillet et al., Triton, MAPL 2019。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tile 与占用率是离散搜索，不是会计恒等式。</li><li>按形状桶离线调、热路径查表；验收数值。</li><li>布局与 dtype 必须进缓存键。</li><li>动态 \\(n\\) 要量化到桶，否则每步重搜。</li><li>FA 家族已调过的核不要再套一层网格。</li><li>下一课：TP 上的自定义 allreduce。</li><li>出处：Chen et al., 2018；Zheng et al., 2020。</li></ul>',7))])}const f=o(p,[["render",c]]);export{D as __pageData,f as default};
